#include "database.hpp"
#include <thread>
#include <sstream>
namespace ps {
static const std::map<std::string,std::string> slugs={{"E0","eng.1"},{"E1","eng.2"},{"E2","eng.3"},{"E3","eng.4"},{"EC","eng.5"},{"SC0","sco.1"},{"SC1","sco.2"},{"SC2","sco.3"},{"SC3","sco.4"},{"SP1","esp.1"},{"SP2","esp.2"},{"I1","ita.1"},{"I2","ita.2"},{"F1","fra.1"},{"F2","fra.2"},{"D1","ger.1"},{"D2","ger.2"},{"N1","ned.1"},{"B1","bel.1"},{"P1","por.1"},{"T1","tur.1"},{"G1","gre.1"}};
static std::string norm(std::string s){
    const std::map<std::string,std::string> letters={{"á","a"},{"à","a"},{"â","a"},{"ä","a"},{"ã","a"},{"Á","a"},{"é","e"},{"è","e"},{"ê","e"},{"É","e"},{"í","i"},{"ï","i"},{"ó","o"},{"ô","o"},{"ö","o"},{"Ó","o"},{"ú","u"},{"ü","u"},{"ñ","n"},{"ç","c"}};
    for(auto&[a,b]:letters){size_t at=0;while((at=s.find(a,at))!=std::string::npos){s.replace(at,a.size(),b);at+=b.size();}}
    std::string out;for(unsigned char c:s)if(std::isalnum(c)&&c<128)out+=char(std::tolower(c));
    static const std::map<std::string,std::string> aliases={{"atleticomadrid","athmadrid"},{"atleticodemadrid","athmadrid"},{"athleticclub","athbilbao"},{"athleticbilbao","athbilbao"},{"racingdesantander","santander"},{"racingsantander","santander"},{"espanyol","espanol"},{"deportivolacoruna","lacoruna"},{"deportivo","lacoruna"},{"realsociedad","sociedad"},{"realbetis","betis"},{"rayovallecano","vallecano"},{"celtavigo","celta"},{"manchesterunited","manunited"},{"manchesterutd","manunited"},{"manchestercity","mancity"},{"newcastleunited","newcastle"},{"nottinghamforest","nottmforest"},{"wolverhamptonwanderers","wolves"},{"westhamunited","westham"},{"tottenhamhotspur","tottenham"},{"brightonhovealbion","brighton"},{"bournemouth","bournemouth"},{"parissaintgermain","parissg"},{"psg","parissg"},{"olympiquelyonnais","lyon"},{"olympiquedemarseille","marseille"},{"internazionale","inter"},{"intermilan","inter"},{"acmilan","milan"},{"asroma","roma"},{"borussiadortmund","dortmund"},{"bayernmunchen","bayernmunich"},{"bayernmunich","bayernmunich"},{"eintrachtfrankfurt","einfrankfurt"},{"borussiamonchengladbach","mgladbach"},{"borussiamgladbach","mgladbach"},{"bayerleverkusen","leverkusen"},{"vfb stuttgart","stuttgart"},{"vflwolfsburg","wolfsburg"},{"mainz05","mainz"},{"vflbochum","bochum"},{"fcstpauli","stpauli"},{"fcaugsburg","augsburg"},{"tsghoffenheim","hoffenheim"},{"fckoeln","fckoln"},{"fcbarcelona","barcelona"}};
    if(auto i=aliases.find(out);i!=aliases.end())return i->second;return out;
}
static bool same(const std::string& a,const std::string& b){auto x=norm(a),y=norm(b);if(x==y)return true;return std::min(x.size(),y.size())>=5&&(x.ends_with(y)||y.ends_with(x));}
static std::string str(const json& j,const char* key){if(!j.contains(key)||j[key].is_null())return "";return j[key].is_string()?j[key].get<std::string>():j[key].dump();}
static int integer(const json& j,const char* key,int fallback=-1){try{return std::stoi(str(j,key));}catch(...){return fallback;}}
static std::string number(const std::map<std::string,double>& s,const std::string& k){auto it=s.find(k);return it==s.end()?"NULL":std::to_string(it->second);}
static int player(Database& db,const json& athlete){auto id=integer(athlete,"id");if(id<0)return 0;db.exec("INSERT INTO player(provider,external_id,name) VALUES(3,"+std::to_string(id)+","+db.quote(str(athlete,"displayName"))+") ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),name=VALUES(name)");return int(db.insertId());}
static void summary(Database& db,const Match& m,const json& doc){
    int players=0;auto mid=std::to_string(m.id);if(doc.contains("rosters"))for(auto& group:doc["rosters"]){if(!group.contains("roster")||!group["roster"].is_array())continue;int team=str(group,"homeAway")=="home"?m.home:m.away;
        for(auto& r:group["roster"]){if(!r.contains("athlete"))continue;int pid=player(db,r["athlete"]);if(!pid)continue;++players;auto metrics=parseEspnMetrics(r,doc);auto stats=metrics.stats;if(metrics.minutes>=0)stats["minutesPlayed"]=metrics.minutes;
            std::string starter=r.contains("starter")&&r["starter"].is_boolean()?(r["starter"].get<bool>()?"1":"0"):"NULL",pos=r.contains("position")?str(r["position"],"abbreviation"):"";
            std::string q="INSERT INTO appearance(fixture_id,team_id,player_id,starter,position,shirt,minutes,goals,assists,shots,shots_on,passes,tackles,yellow,red) VALUES("+mid+","+std::to_string(team)+","+std::to_string(pid)+","+starter+","+db.quote(pos)+","+(integer(r,"jersey")<0?"NULL":std::to_string(integer(r,"jersey")))+",";
            const char* keys[]={"minutesPlayed","totalGoals","goalAssists","totalShots","shotsOnTarget","totalPasses","totalTackles","yellowCards","redCards"};for(int k=0;k<9;++k){if(k)q+=",";q+=number(stats,keys[k]);}q+=") ON DUPLICATE KEY UPDATE starter=VALUES(starter),position=VALUES(position),shirt=VALUES(shirt),minutes=COALESCE(VALUES(minutes),minutes),goals=VALUES(goals),assists=VALUES(assists),shots=VALUES(shots),shots_on=VALUES(shots_on),passes=VALUES(passes),tackles=VALUES(tackles),yellow=VALUES(yellow),red=VALUES(red)";db.exec(q);
            db.exec("UPDATE appearance SET minutes_source="+(metrics.minutes>=0?std::to_string(metrics.minutesSource):"minutes_source")+",rating=COALESCE("+(metrics.rating?std::to_string(*metrics.rating):"NULL")+",rating),studio_rating="+(metrics.studioRating?std::to_string(*metrics.studioRating):"NULL")+" WHERE fixture_id="+mid+" AND player_id="+std::to_string(pid));
            for(auto& [key,v]:stats){if(!std::isfinite(v)||std::abs(v)>1e8)continue;db.exec("INSERT INTO statistic_type(name) VALUES("+db.quote((key=="minutesPlayed"&&metrics.minutesSource==2?"derived.":"espn.")+key)+") ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)");auto sid=db.insertId();db.exec("REPLACE INTO appearance_stat(fixture_id,player_id,statistic_id,value) VALUES("+mid+","+std::to_string(pid)+","+std::to_string(sid)+","+std::to_string(v)+")");}
        }}
    if(doc.contains("boxscore")&&doc["boxscore"].contains("teams")&&m.h[0]>=0)for(auto& group:doc["boxscore"]["teams"]){bool home=str(group,"homeAway")=="home";int tid=home?m.home:m.away;std::map<std::string,double> stats;for(auto& stat:group.value("statistics",json::array()))try{stats[str(stat,"name")]=std::stod(str(stat,"displayValue"));}catch(...){}
        std::string suffix=home?"h":"a";db.exec("UPDATE fixture SET c"+suffix+"=COALESCE(c"+suffix+","+number(stats,"wonCorners")+"),y"+suffix+"=COALESCE(y"+suffix+","+number(stats,"yellowCards")+"),r"+suffix+"=COALESCE(r"+suffix+","+number(stats,"redCards")+") WHERE id="+mid);
        db.exec("INSERT INTO team_match_extra(fixture_id,team_id,shots,shots_on,possession,fouls,offsides,saves,passes) VALUES("+mid+","+std::to_string(tid)+","+number(stats,"totalShots")+","+number(stats,"shotsOnTarget")+","+number(stats,"possessionPct")+","+number(stats,"foulsCommitted")+","+number(stats,"offsides")+","+number(stats,"saves")+","+number(stats,"totalPasses")+") ON DUPLICATE KEY UPDATE shots=COALESCE(VALUES(shots),shots),shots_on=COALESCE(VALUES(shots_on),shots_on),possession=COALESCE(VALUES(possession),possession),fouls=COALESCE(VALUES(fouls),fouls),offsides=COALESCE(VALUES(offsides),offsides),saves=COALESCE(VALUES(saves),saves),passes=COALESCE(VALUES(passes),passes)");}
    if(doc.contains("keyEvents")){db.exec("DELETE FROM match_event WHERE fixture_id="+mid);int seq=0;for(auto&e:doc["keyEvents"]){auto type=e.value("type",json::object()),clock=e.value("clock",json::object());std::string name=str(type,"type"),detail=str(type,"text");int minute=-1;try{minute=int(std::stod(str(clock,"value"))/60);}catch(...){}db.exec("INSERT INTO match_event(fixture_id,seq,minute,type,detail) VALUES("+mid+","+std::to_string(seq++)+","+(minute<0?"NULL":std::to_string(minute))+","+db.quote(name.substr(0,24))+","+db.quote(detail.substr(0,80))+")");}}
    if(m.h[0]>=0)db.exec("UPDATE fixture SET detail_flags=detail_flags | 32 WHERE id="+mid);
    db.exec("REPLACE INTO import_state(source_key,row_count,note) VALUES("+db.quote("espn-summary:"+mid)+","+std::to_string(players)+","+db.quote(players?"Player records present":"Provider supplied no roster; not assumed complete coverage")+")");
}
void enrichPublicPlayers(Database& db,const std::string& code,int budget,Job& job,bool refreshExisting){
    auto si=slugs.find(code);if(si==slugs.end())throw std::runtime_error("No public lineup mapping for this competition. Use API-Football or CSV.");int league=0;for(auto& l:db.leagues())if(l.provider==0&&l.key==code)league=l.id;if(!league)throw std::runtime_error("Import this league's public match history first.");
    auto rows=db.matches(league);std::map<std::string,std::vector<Match>,std::greater<std::string>> dates;for(auto&m:rows)if(m.date<=addDays(today(),7)&&(refreshExisting?bool(m.details&32):!(m.details&32)))dates[m.date].push_back(m);
    int requests=0,enriched=0,unmatched=0;auto get=[&](const std::string& path){job.check();if(requests>=budget)throw std::runtime_error("Request limit reached");if(requests)for(int i=0;i<5;++i){job.check();std::this_thread::sleep_for(std::chrono::milliseconds(100));}++requests;job.message("Public player backfill "+code+": request "+std::to_string(requests)+" / "+std::to_string(budget));auto d=json::parse(httpGet("https://site.api.espn.com/apis/site/v2/sports/soccer/"+si->second+"/"+path));if(d.contains("code")&&d["code"].is_number()&&d["code"].get<int>()>=400)throw std::runtime_error("Public feed rejected this request; coverage is not guaranteed.");return d;};
    for(auto&[date,matches]:dates){job.check();if(requests>=budget)break;auto marker="espn-date:"+si->second+":"+date;bool cached=!db.query("SELECT source_key FROM import_state WHERE source_key="+db.quote(marker)).empty();
        if(!cached||date>=today()){std::string day=date;day.erase(std::remove(day.begin(),day.end(),'-'),day.end());auto doc=get("scoreboard?dates="+day+"&limit=1000");if(!doc.contains("events"))throw std::runtime_error("Missing events in public feed");for(auto&e:doc["events"]){if(!e.contains("competitions")||e["competitions"].empty())continue;std::string home,away;for(auto& team:e["competitions"][0]["competitors"]){auto name=str(team["team"],"displayName");if(str(team,"homeAway")=="home")home=name;else away=name;}std::vector<long long> candidates;for(auto&m:matches)if(same(home,m.homeName)&&same(away,m.awayName))candidates.push_back(m.id);if(candidates.size()==1)db.exec("INSERT INTO provider_fixture_link(provider,external_id,fixture_id) VALUES(3,"+str(e,"id")+","+std::to_string(candidates[0])+") ON DUPLICATE KEY UPDATE fixture_id=VALUES(fixture_id)");else ++unmatched;}if(date<today())db.exec("REPLACE INTO import_state(source_key,note) VALUES("+db.quote(marker)+",'Scoreboard scanned; matching requires both team names')");}
        for(auto&m:matches){if(requests>=budget)break;auto link=db.query("SELECT external_id FROM provider_fixture_link WHERE provider=3 AND fixture_id="+std::to_string(m.id));if(link.empty())continue;auto doc=get("summary?event="+*link[0][0]);db.exec("START TRANSACTION");try{summary(db,m,doc);db.exec("COMMIT");++enriched;}catch(...){db.exec("ROLLBACK");throw;}job.progress=double(requests)/budget;}
    }
    job.message("Public player backfill: "+std::to_string(enriched)+" match summaries, "+std::to_string(unmatched)+" unmatched team-name pairs. "+(requests>=budget?"Budget reached; rerun to resume older matches.":"Available dates scanned; source coverage may be incomplete."));
}
}
